#include <stdio.h>
#include <string.h>

int main(void)
{
    FILE *in = fopen("scores.txt", "r");
    if (in == NULL) {
        perror("scores.txt");
        return 1;
    }

    char line[128];
    int number = 0;
    while (fgets(line, sizeof line, in) != NULL) {
        line[strcspn(line, "\n")] = '\0';
        number++;
        printf("%d: %s (%zu chars)\n", number, line, strlen(line));
    }
    fclose(in);
    return 0;
}

#include <stdio.h>

int main(void)
{
    FILE *in = fopen("scores.txt", "r");
    if (in == NULL) {
        perror("scores.txt");
        return 1;
    }

    char name[32];
    int score, total = 0, count = 0;
    while (fscanf(in, "%31s %d", name, &score) == 2) {
        total += score;
        count++;
        if (score >= 85) printf("%s passed with distinction\n", name);
    }
    fclose(in);

    if (count > 0) {
        printf("average of %d scores: %.1f\n", count, (double)total / count);
    }
    return 0;
}

#include <stdio.h>

typedef struct {
    int id;
    double balance;
} Account;

int main(void)
{
    Account out[2] = {{1, 250.75}, {2, -12.5}};

    FILE *f = fopen("accounts.bin", "wb");
    if (f == NULL) { perror("accounts.bin"); return 1; }
    size_t written = fwrite(out, sizeof out[0], 2, f);
    fclose(f);
    printf("wrote %zu records of %zu bytes\n", written, sizeof out[0]);

    Account in[2];
    f = fopen("accounts.bin", "rb");
    if (f == NULL) { perror("accounts.bin"); return 1; }
    size_t read = fread(in, sizeof in[0], 2, f);
    fclose(f);

    for (size_t i = 0; i < read; i++) {
        printf("account %d: %.2f\n", in[i].id, in[i].balance);
    }
    return 0;
}

